#!/usr/bin/env python3
"""Assemble the digest-bearing release archive from reviewed build outputs."""

import argparse
import gzip
import hashlib
from pathlib import Path
import tarfile
import tempfile


def digest(path):
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def assemble(panel, xray, geo, certbot, output):
    files = {
        "x-ui/x-ui": panel,
        "x-ui/bin/xray-linux-amd64": xray,
        **{f"x-ui/bin/{name}": geo / name for name in ("geoip.dat", "geosite.dat")},
        **{f"x-ui/certbot/{path.name}": path for path in certbot.iterdir()},
    }
    if any(path.is_symlink() or not path.is_file() for path in files.values()):
        raise ValueError("Release input must be a regular file")
    with tempfile.NamedTemporaryFile() as manifest:
        for path in sorted(certbot.iterdir()):
            if path.name == "SHA256SUMS":
                raise ValueError("The Certbot manifest must be generated by the assembler")
            manifest.write(f"{digest(path)}  {path.name}\n".encode("ascii"))
        manifest.flush()
        print(f"{digest(Path(manifest.name))}  x-ui/certbot/SHA256SUMS")
        files["x-ui/certbot/SHA256SUMS"] = Path(manifest.name)
        with output.open("xb") as raw, gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0) as compressed, \
                tarfile.open(fileobj=compressed, mode="w|", format=tarfile.PAX_FORMAT) as archive:
            for directory in ("x-ui", "x-ui/bin", "x-ui/certbot"):
                entry = tarfile.TarInfo(directory)
                entry.type = tarfile.DIRTYPE
                entry.mode = 0o755
                archive.addfile(entry)
            for name, path in sorted(files.items()):
                entry = tarfile.TarInfo(name)
                entry.size = path.stat().st_size
                entry.mode = 0o755 if name in {"x-ui/x-ui", "x-ui/bin/xray-linux-amd64"} else 0o644
                with path.open("rb") as stream:
                    archive.addfile(entry, stream)
    print(f"{digest(output)}  {output.name}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("panel", "xray", "geo", "certbot", "output"):
        parser.add_argument("--" + name, required=True, type=Path)
    arguments = parser.parse_args()
    assemble(**vars(arguments))
